local StoreDailyChestDialog = Class("StoreDailyChestDialog")

--region lifecycle
function StoreDailyChestDialog:__init()
    self._openId = StoreConstants.OpenIds.StoreCommonChest
    self._chestData = nil
end

function StoreDailyChestDialog:__delete()
    self._openId = nil
    self._chestData = nil
end

function StoreDailyChestDialog:Awake()
    
end

function StoreDailyChestDialog:OnInitialize()
    ---@type Engine.Lib.CoWait
    local coWait = CoWait.Start():Coroutine(util.cs_generator(function()
        local param = self.controller.Argument.parameters
        self._itemData = param.ItemData
        self:InitHandler()
        self:InitData()
        self:CheckRewards()
    end))
