--region init
function StoreDailyChestDialog:InitHandler()
    self.LoopList:InitListView(0, Bind(self, self.OnRefreshIndex))
    SetButtonAction(self.BtnClose, Bind(self, self.BtnCloseClickHandler))
    SetButtonAction(self.ImgBg, Bind(self, self.BtnCloseClickHandler))
end

function StoreDailyChestDialog:InitData()
    local comp = StoreUtils.GetStoreComp()
    local dataKey = StoreUtils.GetDataKey(self._openId)
    self._chestData = comp.AllStores[dataKey]
    -- 初始化明日奖励
    local initNextRewards = false
    for i, v in ipairs(self._chestData) do
        if v.status == RewardsStatus.LOCKED and not initNextRewards then
            v.nextRewards = true
            initNextRewards = true
        else
            v.nextRewards = false
        end
    end
end
--endregion init

