function StoreDailyChestDialog:OnRefreshIndex(listView, index, row, column)
    local cell = listView:NewListViewItem(ItemCell)
    local data = self._chestData[index + 1]
    local chestCellScr = CfUtils.GetLuaScr(cell, ItemCellScrPath)
    chestCellScr:RefreshCell(data)
    return cell
end
