--region private
---检查奖励是否可领取
function StoreDailyChestDialog:CheckRewards()
    for i, v in ipairs(checkTable(self._chestData)) do
        if checkInt(v.status) == RewardsStatus.CAN_RECEIVE then
            GameUtils.Request(Interfaces.StoreDrawDailyGift, { id = v.id, num = 1, currency = 0 },
                function(request, response)
                    if checkInt(response.errCode) == 0 then
                        StoreUtils.RefreshStock(StoreConstants.OpenIds.Gift, self._itemData.productId, 1)
                        GoodsUtils.DrawRewards(response.data.rewards)
                        UIModule.OpenDialog({ id = Constants.UITypeIds.UICommonRewardPop, parameters = { rewards = response.data.rewards } })
                        v.status = RewardsStatus.RECEIVED
                        self:RefreshSelf()
                        GameUtils.UpdateServerRedPointData({unMallChest = -1})
                    end
                end
            )
            return 
        end
    end
    
    -- 7日奖励是否全部领取
    for i, v in ipairs(self._chestData) do
        if v.status ~= RewardsStatus.RECEIVED then
            self:RefreshSelf()
            return
        end
    end
    -- 全部领取后刷新为下一轮奖励
    for i, v in ipairs(self._chestData) do
        v.nextRewards = i == 1
        v.status = RewardsStatus.LOCKED
    end
    self:RefreshSelf()
end
---刷新列表
function StoreDailyChestDialog:RefreshScroll()
    GameUtils.ReloadData(self.LoopList, #self._chestData)
end
--endregion private

return StoreDailyChestDialog